{
	// --- Chat ---
	"inlineChat.affordance": "editor",
	"chat.tools.terminal.autoApprove": {
		"scripts/test.bat": true,
		"scripts/test.sh": true,
		"scripts/test-integration.bat": true,
		"scripts/test-integration.sh": true,
	},
	"chat.editing.explainChanges.enabled": true,
	"chat.requestQueuing.defaultAction": "queue",
	// --- Editor ---
	"editor.insertSpaces": false,
	"editor.experimental.asyncTokenization": true,
	"editor.experimental.asyncTokenizationVerification": true,
	"editor.occurrencesHighlightDelay": 0,
	// "editor.experimental.preferTreeSitter.typescript": true,
	// "editor.experimental.preferTreeSitter.regex": true,
	// "editor.experimental.preferTreeSitter.css": true,
	// --- Language Specific ---
	"[plaintext]": {
		"files.insertFinalNewline": false
	},
	"[typescript]": {
		"editor.formatOnSave": true
	},
	"[javascript]": {
		"editor.formatOnSave": true
	},
	"[rust]": {
		"editor.defaultFormatter": "rust-lang.rust-analyzer",
		"editor.formatOnSave": true,
	},
	"[github-issues]": {
		"editor.wordWrap": "on"
	},
	// --- Files ---
	"files.trimTrailingWhitespace": true,
	"files.insertFinalNewline": true,
	"files.exclude": {
		".git": true,
		".build": true,
		".profile-oss": true,
		"**/*.tsbuildinfo": true,
		"**/.DS_Store": true,
		".vscode-test": true,
		"cli/target": true,
		"build/**/*.js.map": true,
		"build/**/*.js": {
			"when": "$(basename).ts"
		},
	},
	"files.associations": {
		"cglicenses.json": "jsonc",
		"*.tst": "typescript"
	},
	"files.readonlyInclude": {
		"**/node_modules/**/*.*": true,
		"**/yarn.lock": true,
		"**/package-lock.json": true,
		"**/Cargo.lock": true,
		"out/**": true,
		"out-build/**": true,
		"out-vscode/**": true,
		"out-vscode-reh/**": true,
		"extensions/**/dist/**": true,
		"extensions/**/out/**": true,
		"extensions/terminal-suggest/src/completions/upstream/**": true,
		"test/smoke/out/**": true,
		"test/automation/out/**": true,
		"src/vs/platform/agentHost/common/state/protocol/**": true,
		"src/vs/platform/agentHost/node/codex/protocol/generated/**": true,
		"test/integration/browser/out/**": true,
		// "src/vs/sessions/**": true
	},
	// --- Search ---
	"search.exclude": {
		"**/node_modules": true,
		"cli/target/**": true,
		".build/**": true,
		"out/**": true,
		"out-build/**": true,
		"out-vscode/**": true,
		"i18n/**": true,
		"extensions/**/dist/**": true,
		"extensions/**/out/**": true,
		"test/smoke/out/**": true,
		"test/automation/out/**": true,
		"test/integration/browser/out/**": true,
		"src/vs/base/test/common/filters.perf.data.js": true,
		"src/vs/base/test/node/uri.perf.data.txt": true,
		"src/vs/workbench/api/test/browser/extHostDocumentData.test.perf-data.ts": true,
		"src/vs/base/test/node/uri.test.data.txt": true,
		"src/vs/editor/test/node/diffing/fixtures/**": true,
		"build/loader.min": true,
		"**/*.snap": true,
	},
	// --- TypeScript ---
	"js/ts.experimental.useTsgo": true,
	"js/ts.tsdk.path": "node_modules/typescript/lib",
	"js/ts.preferences.importModuleSpecifier": "relative",
	"js/ts.preferences.quoteStyle": "single",
	"js/ts.tsc.autoDetect": "off",
	"js/ts.preferences.autoImportFileExcludePatterns": [
		"@xterm/xterm",
		"@xterm/headless",
		"node-pty",
		"vscode-notebook-renderer",
		"src/vs/workbench/workbench.web.main.internal.ts"
	],
	// --- Languages ---
	"json.schemas": [
		{
			"fileMatch": [
				"cgmanifest.json"
			],
			"url": "https://www.schemastore.org/component-detection-manifest.json",
		},
		{
			"fileMatch": [
				"cglicenses.json"
			],
			"url": "./.vscode/cglicenses.schema.json"
		}
	],
	"css.format.spaceAroundSelectorSeparator": true,
	// --- Git ---
	"git.ignoreLimitWarning": true,
	"git.branchProtection": [
		"main",
		"main-*",
		"distro",
		"release/*"
	],
	"git.branchProtectionPrompt": "alwaysCommitToNewBranch",
	"git.branchRandomName.enable": true,
	"git.pullBeforeCheckout": true,
	"git.mergeEditor": true,
	"git.diagnosticsCommitHook.enabled": true,
	"git.diagnosticsCommitHook.sources": {
		"*": "error",
		"ts": "warning",
		"eslint": "warning"
	},
	"git.worktreeIncludeFiles": [
		"product.overrides.json",
		"**/node_modules/**",
	],
	// --- GitHub ---
	"githubPullRequests.experimental.createView": true,
	"githubPullRequests.assignCreated": "${user}",
	"githubPullRequests.defaultMergeMethod": "squash",
	"githubPullRequests.ignoredPullRequestBranches": [
		"main"
	],
	"githubPullRequests.codingAgent.enabled": true,
	"githubPullRequests.codingAgent.uiIntegration": true,
	"githubPullRequests.enableAttestationCommits": true,
	// --- Testing & Debugging ---
	"testing.autoRun.mode": "rerun",
	"debug.javascript.terminalOptions": {
		"outFiles": [
			"${workspaceFolder}/out/**/*.js",
			"${workspaceFolder}/build/**/*.js"
		]
	},
	"extension-test-runner.debugOptions": {
		"outFiles": [
			"${workspaceFolder}/extensions/*/out/**/*.js",
		]
	},
	// --- Coverage ---
	"lcov.path": [
		"./.build/coverage/lcov.info",
		"./.build/coverage-single/lcov.info"
	],
	"lcov.watch": [
		{
			"pattern": "**/*.test.js",
			"command": "${workspaceFolder}/scripts/test.sh --coverage --run ${file}",
			"windows": {
				"command": "${workspaceFolder}\\scripts\\test.bat --coverage --run ${file}"
			}
		}
	],
	// --- Tools ---
	"npm.exclude": "**/extensions/**",
	"eslint.useFlatConfig": true,
	"emmet.excludeLanguages": [],
	"gulp.autoDetect": "off",
	"rust-analyzer.linkedProjects": [
		"cli/Cargo.toml"
	],
	"conventionalCommits.scopes": [
		"tree",
		"scm",
		"grid",
		"splitview",
		"table",
		"list",
		"git",
		"sash"
	],
	// --- Workbench ---
	"editor.aiStats.enabled": true, // Team selfhosting on ai stats
	"azureMcp.enabledServices": [
		"kusto" // Needed for kusto tool in data.prompt.md
	],
	"azureMcp.serverMode": "all",
	"azureMcp.readOnly": true,
	"debug.breakpointsView.presentation": "tree",
	"chat.agentSkillsLocations": {
		".github/skills/.local": true,
		".agents/skills/.local": true,
		".claude/skills/.local": true,
	},
	"workbench.colorCustomizations": {
		"activityBar.background": "#464F0E",
		"titleBar.activeBackground": "#697715",
		"titleBar.inactiveBackground": "#464F0E",
		"statusBar.background": "#464F0E",
		"statusBar.debuggingBackground": "#464F0E",
		"statusBar.noFolderBackground": "#464F0E",
		"activityBar.foreground": "#FFFFFF",
		"activityBar.inactiveForeground": "#FFFFFF",
		"titleBar.activeForeground": "#FFFFFF",
		"titleBar.inactiveForeground": "#FFFFFF",
		"statusBar.foreground": "#FFFFFF",
		"statusBar.debuggingForeground": "#FFFFFF",
		"statusBar.noFolderForeground": "#FFFFFF"
	}
}
